declare(strict_types=1);require_once __DIR__.'/config/sales_step15.php';require_once __DIR__.'/config/purchase_step14.php';$error=null;$m=['legacy'=>0,'products'=>0,'sales'=>0,'customers'=>0,'receivable'=>0.0,'credit_due'=>0.0,'delivered'=>0,'followups'=>0,'stock'=>0.0,'stock_value'=>0.0,'supplier_due'=>0.0,'pending_receipts'=>0];
try{$pdo=business_db();sales_step15_ensure($pdo);sales_step15_backfill($pdo);purchase_step14_ensure($pdo);$ctx=sales_step15_context($pdo);$orgId=(int)$ctx['organization_id'];$s=$pdo->prepare("SELECT SUM(mapping_status='mapped') FROM raw_source_records WHERE organization_id=? AND source_dataset IN ('New UMS','Volume Points','First & Second Set','Active UMS Month_Wise','Renewal UMS','Monthely_Income','Royalty_Tracking','Extra Order for Customer')");$s->execute([$orgId]);$m['legacy']=(int)$s->fetchColumn();$m['products']=(int)$pdo->query("SELECT COUNT(*) FROM products WHERE organization_id=".$orgId." AND status='active'")->fetchColumn();foreach(sales_step15_sales_rows($pdo,$orgId) as $r){if($r['sale_status']!=='active')continue;$m['sales']++;$m['receivable']+=(float)$r['receivable_amount'];$m['credit_due']+=(float)$r['customer_credit_due'];if($r['delivery_status']==='delivered')$m['delivered']++;}$m['customers']=(int)$pdo->query("SELECT COUNT(*) FROM crm_customers WHERE organization_id=".$orgId." AND status='active'")->fetchColumn();$s=$pdo->prepare("SELECT COUNT(*) FROM crm_interactions WHERE organization_id=? AND status='open'");$s->execute([$orgId]);$m['followups']=(int)$s->fetchColumn();$loc=inventory_step13_location_id($pdo,$orgId);foreach(inventory_step13_stock_rows($pdo,$orgId,$loc) as $r){$m['stock']+=(float)$r['sellable_stock'];$m['stock_value']+=(float)$r['known_value'];}foreach(purchase_step14_bill_rows($pdo,$orgId,'active') as $b){$st=purchase_step14_recalc_bill($pdo,$orgId,(int)$b['id']);$m['supplier_due']+=$st['outstanding'];if($st['receipt_status']!=='received')$m['pending_receipts']++;}}catch(Throwable $e){$error=$e->getMessage();}
